package com.education.music.app.controller;

import com.education.music.app.entity.VO.GoodsVO;
import com.education.music.app.entity.page.CommonPager;
import com.education.music.app.entity.req.GoodsGetReq;
import com.education.music.app.entity.req.ProductExgReq;
import com.education.music.app.entity.req.query.GoodsQuery;
import com.education.music.app.service.mall.GoodsService;
import com.education.music.core.DO.mall.GoodsRecommendDO;
import com.education.music.core.annotation.RateLimit;
import com.education.music.core.common.SmsConstants;
import com.education.music.core.context.ThreadContextHolder;
import com.education.music.core.enums.ErrorCode;
import com.education.music.core.result.CommonResult;

import com.education.music.core.service.AliSmsService;
import java.util.List;
import java.util.Map;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import javax.validation.constraints.NotBlank;

@RestController
public class GoodsController {

	@Autowired
	private GoodsService goodsService;

	@Autowired
	private AliSmsService smsService;

	/**
	 * 商品列表
	 */
	@PostMapping(value = "/goods/list")
	public CommonResult list(@Validated @RequestBody GoodsQuery req) {
		CommonPager<GoodsVO> commonPager = goodsService.queryPageGoods(req);
		return CommonResult.success(commonPager);
	}

	/**
	 * 推荐商品
	 */
	@PostMapping(value = "/goods/getRecommendGoods")
	public CommonResult getRecommendGoods() {
		List<GoodsRecommendDO> recommendGoods = goodsService.getRecommendGoods();
		return CommonResult.success(recommendGoods);
	}


	/**
	 * 商品列表
	 */
	@PostMapping(value = "/goods/getDetail")
	public CommonResult getDetail(@Validated @RequestBody GoodsGetReq req) {
		Map<String, Object> goodsDetail = goodsService.getGoodsDetail(req.getGoodsId());
		return CommonResult.success(goodsDetail);
	}

	/**
	 * 发送验证码
	 */
	@PostMapping("/goods/sendVcode")
	public CommonResult sendVcode(@NotBlank(message = "电话号码不能为空") String mobile) {
		boolean success = smsService.sendVcodeSms(mobile, SmsConstants.PRODUCT_EXG_PREFIX);
		return success ? CommonResult.success() : CommonResult.error(ErrorCode.SMS_SEND_ERROR);
	}

	@RateLimit(limitNum = 6.0)
	@PostMapping(value = "/goods/exchange")
	public CommonResult exchange(@Validated @RequestBody ProductExgReq req) {
		req.setUserId(ThreadContextHolder.getUserId());
		String orderId = goodsService.exchange(req);
		return CommonResult.success(orderId);
	}
}

