98	
99		public GoodsDO getById(Long goodsId) {
100			GoodsQuery query = GoodsQuery.builder()
101					.onSell(1)
102					.deleted(false)
103					.goodsId(goodsId)
104					.build();
105			return goodsMapper.getGoodsById(query);
106		}
