108		public List<GoodsVO> queryGoods(GoodsQuery req) {
109			return goodsMapper.selectByQuery(req);
110		}
111	
112		public CommonPager<GoodsVO> queryPageGoods(GoodsQuery req) {
113			Long userId = ThreadContextHolder.getUserId();
114			String keyword = req.getKeyword();
115	
116			// 添加到搜索历史
117			if (userId != null && StrUtil.isNotBlank(req.getKeyword())) {
118				SearchHistoryDO searchHistoryDO = new SearchHistoryDO();
119				searchHistoryDO.setKeyword(keyword);
120				searchHistoryDO.setUserId(userId);
121				searchHistoryDO.setFrom("wx");
122				searchHistoryService.save(searchHistoryDO);
123			}
124	
125			req.setOrderByClause("p.create_time desc");
126	
127			// 查询列表数据
128			req.setOnSell(1);
129			List<GoodsVO> records = goodsMapper.selectByQuery(req);
130	
131			records.forEach(goodsVO -> {
132				Long goodsId = goodsVO.getId();
133				List<GoodsProductDO> products = goodsProductService.findByGid(goodsId);
134				List<GoodsProductDO> collect = products.stream().sorted(new Comparator<GoodsProductDO>() {
135					@Override
136					public int compare(GoodsProductDO o1, GoodsProductDO o2) {
137						return o1.getPrice().compareTo(o2.getPrice());
138					}
139				}).collect(Collectors.toList());
140				goodsVO.setPrice(collect.get(0).getPrice());
141				goodsVO.setDiscountPrice(collect.get(0).getDiscountPrice());
142			});
143	
144			return PageResultUtils.result(() -> records, () -> {
145				if (CollectionUtil.isNotEmpty(records)) {
146					GoodsVO recordVO = records.get(records.size() - 1);
147					return recordVO.getId();
148				}
149				return null;
150			});
151		}
152	
153		public Map<String, Object> getGoodsDetail(Long goodsId) {
154			GoodsQuery query = GoodsQuery.builder()
155					.onSell(1)
156					.deleted(false)
157					.goodsId(goodsId)
158					.build();
159			GoodsDO goodsDO = goodsMapper.getGoodsById(query);
160			if (goodsDO == null) {
161				throw new GoodsException(ErrorCode.GOODS_NOT_EXIST);
162			}
163			List<GoodsProductDO> products = goodsProductService.findByGid(goodsId);
164			List<GoodsSpecificationDO> specifications = specificationService.queryByGid(goodsId);
165			List<GoodsAttributeDO> attributes = attributeService.queryByGid(goodsId);
166	
167			Long categoryId = goodsDO.getCategoryId();
168			CategoryDO category = categoryService.findById(categoryId);
169			Long[] categoryIds = new Long[]{};
170			if (category != null) {
171				Long parentCategoryId = category.getPid();
172				categoryIds = new Long[]{parentCategoryId, categoryId};
173			}
174	
175			Map<String, Object> data = new HashMap<>();
176			data.put("goods", goodsDO);
177			data.put("specifications", specifications);
178			data.put("products", products);
179			data.put("attributes", attributes);
180			data.put("categoryIds", categoryIds);
181	
182			return data;
183		}
184	
185		/**
186		 * 兑换
187		 */
188		public String exchange(ProductExgReq productExgReq) {
189			Long goodsId = productExgReq.getProductId();
190			Long userId = productExgReq.getUserId();
191	
192			String lockKey = CreditsConstants.PRODUCT_EXG_REDIS_LOCK + userId;
193	
194			// 对每个用户加锁
195			boolean success = RedissLockUtil.tryLock(lockKey, TimeUnit.SECONDS, 5, 20);
196	
197			if (!success) {
198				throw new GoodsException(ErrorCode.SYSTEM_BUSY);
199			}
200	
201			try {
202				// 必要的校验
203				checkSecurity(productExgReq);
204	
205				// 用户信息校验
206				checkUserStatus(userId);
207				log.info("用户userId：{}，信息校验通过", userId);
208	
209				// 商品信息校验
210				checkProductStatus(userId, goodsId);
211				log.info("商品：{}，信息校验通过", goodsId);
212	
213				UserDO userDO = userService.getUserById(userId);
214	
215				GoodsQuery query = GoodsQuery.builder()
216						.onSell(1)
217						.deleted(false)
218						.goodsId(goodsId)
219						.build();
220				GoodsDO goodsDO = goodsMapper.getGoodsById(query);
221	
222				OrderInfo orderInfo = OrderInfo.builder()
223						.userId(userId)
224						.productId(goodsId)
225						.mobile(userDO.getMobile())
226						.consignee(productExgReq.getConsignee())
227						.deliveryAddress(productExgReq.getDeliveryAddress())
228						.deliveryType(productExgReq.getDeliveryType())
229						.productType(CreditsTypeEnum.PRODUCT.getType())
230						//.costCredits(goodsDO.getCredits())
231						.freeTimes(0)
232						.build();
233				return checkProdStockAndCreateOrder(orderInfo);
234			} catch (GoodsException e) {
235				throw e;
236			} catch (Exception e) {
237				log.warn("兑换商品失败", e);
238				throw e;
239			} finally {
240				RedissLockUtil.unlock(lockKey);
241			}
242		}
243	
244		/**
245		 * 安全校验，目前只支持验证码
246		 */
247		private void checkSecurity(ProductExgReq productExgReq) {
248			if (appConfig.isSmsCheckSwitch()) {
249				if (StringUtils.isBlank(productExgReq.getMobile()) || StringUtils.isBlank(productExgReq.getVcode())) {
250					throw new GoodsException(ErrorCode.VCODE_INVALID);
251				}
252				boolean valid = smsService.validSms(SmsConstants.PRODUCT_EXG_PREFIX, productExgReq.getMobile(),
253						productExgReq.getVcode());
254				if (!valid) {
255					throw new GoodsException(ErrorCode.VCODE_INVALID);
256				}
257			}
258		}
259	
260	
261		/**
262		 * 创建订单
263		 */
264		public String checkProdStockAndCreateOrder(OrderInfo orderInfo) {
265			Long goodsId = orderInfo.getProductId();
266			Long userId = orderInfo.getUserId();
267			Integer credits = orderInfo.getCostCredits();
268	
269			minusProdExgNumLimit(goodsId);
270			minusProdStock(goodsId);
271	
272			GoodsQuery query = GoodsQuery.builder()
273					.onSell(1)
274					.deleted(false)
275					.goodsId(goodsId)
276					.build();
277			GoodsDO goodsDO = goodsMapper.getGoodsById(query);
278	
279			if (goodsDO == null) {
280				throw new GoodsException(ErrorCode.GOODS_NOT_EXIST);
281			}
282			TransactionTemplate transactionTemplate = new TransactionTemplate(transactionManager);
283			transactionTemplate.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);
284			transactionTemplate.setTimeout(5);
285			transactionTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED);
286			return transactionTemplate.execute(status -> {
287				String orderId = null;
288				try {
289					// 扣减积分
290					boolean success = operationService.addUserScore(userId, Math.negateExact(credits),
291							OperationRecordEm.PRODUCT_CONSUME);
292	
293					// 创建订单
294					if (success) {
295						orderId = orderService.createOrder(orderInfo);
296						log.info("订单创建成功！订单编号：{}", orderId);
297					}
298				} catch (Exception e) {
299					log.warn("创建订单失败，回滚库存，商品兑换次数数据...", e);
300					rollbackProdStock(goodsId);
301					rollbackProdExgNumLimit(goodsId);
302					throw new GoodsException(ErrorCode.ORDER_OPERATION_ERROR);
303				}
304				return orderId;
305			});
306		}
307	
308	
309		/**
310		 * 判断商品的今日可兑换次数是否超限，若没有则减一
311		 */
312		private void minusProdExgNumLimit(Long productId) {
313			String redisKey = genProductExgNum(productId);
314			Long decr = redisService.decrement(redisKey);
315			if (decr < 0) {
316				rollbackProdExgNumLimit(productId);
317				throw new GoodsException(ErrorCode.EXG_OVER_PROD_LIMIT);
318			}
319			log.info("扣减商品兑换次数成功,商品编号:{},剩余次数:{}", productId, decr);
320		}
321	
322	
323		public void rollbackProdExgNumLimit(Long productId) {
324			String redisKey = genProductExgNum(productId);
325			Long incr = redisService.increment(redisKey);
326			log.info("商品每日兑换次数回滚后数据:{}", incr);
327		}
328	
329	
330		/**
331		 * 判断商品的库存是否超限，若没有则减一
332		 */
333		private void minusProdStock(Long productId) {
334			String redisKey = genProductStockNumRedisKey(productId);
335			Long decr = redisService.decrement(redisKey);
336			if (decr < 0) {
337				rollbackProdStock(productId);
338				rollbackProdExgNumLimit(productId);
339				throw new GoodsException(ErrorCode.GOODS_NO_STOCK);
340			}
341			log.info("扣减商品库存成功,商品编号:{},剩余库存:{}", productId, decr);
342		}
343	
344	
345		public void rollbackProdStock(Long productId) {
346			String redisKey = genProductStockNumRedisKey(productId);
347			Long incr = redisService.increment(redisKey);
348			log.info("库存回滚后数据:{}", incr);
349		}
350	
351	
352		public GoodsDO findById(Long goodsId) {
353			GoodsQuery query = GoodsQuery.builder()
354					.onSell(1)
355					.deleted(false)
356					.goodsId(goodsId)
357					.build();
358			return goodsMapper.getGoodsById(query);
359		}
360	
361	
362		private String genProductExgNum(Long productId) {
363			return CreditsConstants.PRODUCT_EXG_LIMIT_REDIS_KEY_PREFIX + productId;
364		}
365	
366	
367		private String genProductStockNumRedisKey(Long productId) {
368			return CreditsConstants.PRODUCT_STOCK_REDIS_KEY_PREFIX + productId;
