package com.education.music.app.service.mall;

import cn.hutool.core.collection.CollectionUtil;
import cn.hutool.core.util.StrUtil;
import com.education.music.app.common.utils.RedissLockUtil;
import com.education.music.app.entity.DTO.OrderInfo;
import com.education.music.app.entity.VO.GoodsVO;
import com.education.music.app.entity.page.CommonPager;
import com.education.music.app.entity.page.PageResultUtils;
import com.education.music.app.entity.property.MallConfig;
import com.education.music.app.entity.req.ProductExgReq;
import com.education.music.app.entity.req.query.GoodsQuery;
import com.education.music.app.mapper.GoodsMapper;
import com.education.music.app.service.common.RedisService;
import com.education.music.app.service.user.UserService;
import com.education.music.core.DO.mall.CategoryDO;
import com.education.music.core.DO.mall.GoodsAttributeDO;
import com.education.music.core.DO.mall.GoodsDO;
import com.education.music.core.DO.mall.GoodsProductDO;
import com.education.music.core.DO.mall.GoodsRecommendDO;
import com.education.music.core.DO.mall.GoodsSpecificationDO;
import com.education.music.core.DO.mall.OrderDO;
import com.education.music.core.DO.mall.OrderGoodsDO;
import com.education.music.core.DO.mall.OrderRecordDO;
import com.education.music.core.DO.mall.SearchHistoryDO;
import com.education.music.core.DO.user.UserDO;
import com.education.music.core.DO.user.UserGatherDO;
import com.education.music.core.common.CreditsConstants;
import com.education.music.core.common.SmsConstants;
import com.education.music.core.context.ThreadContextHolder;
import com.education.music.core.enums.CreditsTypeEnum;
import com.education.music.core.enums.ErrorCode;
import com.education.music.core.enums.OperationRecordEm;
import com.education.music.core.exception.GoodsException;
import com.education.music.core.service.AliSmsService;
import com.education.music.core.utils.OrderUtil;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

@Slf4j
@Service
public class GoodsService {

	@Autowired
	private GoodsMapper goodsMapper;

	@Autowired
	private OrderService orderService;

	@Autowired
	private UserService userService;

	@Autowired
	private OperationService operationService;

	@Autowired
	private MallConfig appConfig;

	@Autowired
	private RedisService redisService;

	@Autowired
	private AliSmsService smsService;

	@Autowired
	private SearchHistoryService searchHistoryService;

	@Autowired
	private GoodsProductService goodsProductService;

	@Autowired
	private SpecificationService specificationService;

	@Autowired
	private AttributeService attributeService;

	@Autowired
	private CategoryService categoryService;

	@Autowired
	private PlatformTransactionManager transactionManager;

	@Autowired
	private OrderGoodsService orderGoodsService;

	public GoodsDO getById(Long goodsId) {
		GoodsQuery query = GoodsQuery.builder()
				.onSell(1)
				.deleted(false)
				.goodsId(goodsId)
				.build();
		return goodsMapper.getGoodsById(query);
	}

	public List<GoodsVO> queryGoods(GoodsQuery req) {
		return goodsMapper.selectByQuery(req);
	}

	public CommonPager<GoodsVO> queryPageGoods(GoodsQuery req) {
		Long userId = ThreadContextHolder.getUserId();
		String keyword = req.getKeyword();

		// 添加到搜索历史
		if (userId != null && StrUtil.isNotBlank(req.getKeyword())) {
			SearchHistoryDO searchHistoryDO = new SearchHistoryDO();
			searchHistoryDO.setKeyword(keyword);
			searchHistoryDO.setUserId(userId);
			searchHistoryDO.setFrom("wx");
			searchHistoryService.save(searchHistoryDO);
		}

		req.setOrderByClause("p.create_time desc");

		// 查询列表数据
		req.setOnSell(1);
		List<GoodsVO> records = goodsMapper.selectByQuery(req);

		records.forEach(goodsVO -> {
			Long goodsId = goodsVO.getId();
			List<GoodsProductDO> products = goodsProductService.findByGid(goodsId);
			List<GoodsProductDO> collect = products.stream().sorted(new Comparator<GoodsProductDO>() {
				@Override
				public int compare(GoodsProductDO o1, GoodsProductDO o2) {
					return o1.getPrice().compareTo(o2.getPrice());
				}
			}).collect(Collectors.toList());
			goodsVO.setPrice(collect.get(0).getPrice());
			goodsVO.setDiscountPrice(collect.get(0).getDiscountPrice());
		});

		return PageResultUtils.result(() -> records, () -> {
			if (CollectionUtil.isNotEmpty(records)) {
				GoodsVO recordVO = records.get(records.size() - 1);
				return recordVO.getId();
			}
			return null;
		});
	}

	public Map<String, Object> getGoodsDetail(Long goodsId) {
		GoodsQuery query = GoodsQuery.builder()
				.onSell(1)
				.deleted(false)
				.goodsId(goodsId)
				.build();
		GoodsDO goodsDO = goodsMapper.getGoodsById(query);
		if (goodsDO == null) {
			throw new GoodsException(ErrorCode.GOODS_NOT_EXIST);
		}
		List<GoodsProductDO> products = goodsProductService.findByGid(goodsId);
		List<GoodsSpecificationDO> specifications = specificationService.queryByGid(goodsId);
		List<GoodsAttributeDO> attributes = attributeService.queryByGid(goodsId);

		Long categoryId = goodsDO.getCategoryId();
		CategoryDO category = categoryService.findById(categoryId);
		Long[] categoryIds = new Long[]{};
		if (category != null) {
			Long parentCategoryId = category.getPid();
			categoryIds = new Long[]{parentCategoryId, categoryId};
		}

		Map<String, Object> data = new HashMap<>();
		data.put("goods", goodsDO);
		data.put("specifications", specifications);
		data.put("products", products);
		data.put("attributes", attributes);
		data.put("categoryIds", categoryIds);

		return data;
	}

	/**
	 * 兑换
	 */
	public String exchange(ProductExgReq productExgReq) {
		Long goodsId = productExgReq.getProductId();
		Long userId = productExgReq.getUserId();

		String lockKey = CreditsConstants.PRODUCT_EXG_REDIS_LOCK + userId;

		// 对每个用户加锁
		boolean success = RedissLockUtil.tryLock(lockKey, TimeUnit.SECONDS, 5, 20);

		if (!success) {
			throw new GoodsException(ErrorCode.SYSTEM_BUSY);
		}

		try {
			// 必要的校验
			checkSecurity(productExgReq);

			// 用户信息校验
			checkUserStatus(userId);
			log.info("用户userId：{}，信息校验通过", userId);

			// 商品信息校验
			checkProductStatus(userId, goodsId);
			log.info("商品：{}，信息校验通过", goodsId);

			UserDO userDO = userService.getUserById(userId);

			GoodsQuery query = GoodsQuery.builder()
					.onSell(1)
					.deleted(false)
					.goodsId(goodsId)
					.build();
			GoodsDO goodsDO = goodsMapper.getGoodsById(query);

			OrderInfo orderInfo = OrderInfo.builder()
					.userId(userId)
					.productId(goodsId)
					.mobile(userDO.getMobile())
					.consignee(productExgReq.getConsignee())
					.deliveryAddress(productExgReq.getDeliveryAddress())
					.deliveryType(productExgReq.getDeliveryType())
					.productType(CreditsTypeEnum.PRODUCT.getType())
					//.costCredits(goodsDO.getCredits())
					.freeTimes(0)
					.build();
			return checkProdStockAndCreateOrder(orderInfo);
		} catch (GoodsException e) {
			throw e;
		} catch (Exception e) {
			log.warn("兑换商品失败", e);
			throw e;
		} finally {
			RedissLockUtil.unlock(lockKey);
		}
	}

	/**
	 * 安全校验，目前只支持验证码
	 */
	private void checkSecurity(ProductExgReq productExgReq) {
		if (appConfig.isSmsCheckSwitch()) {
			if (StringUtils.isBlank(productExgReq.getMobile()) || StringUtils.isBlank(productExgReq.getVcode())) {
				throw new GoodsException(ErrorCode.VCODE_INVALID);
			}
			boolean valid = smsService.validSms(SmsConstants.PRODUCT_EXG_PREFIX, productExgReq.getMobile(),
					productExgReq.getVcode());
			if (!valid) {
				throw new GoodsException(ErrorCode.VCODE_INVALID);
			}
		}
	}


	/**
	 * 创建订单
	 */
	public String checkProdStockAndCreateOrder(OrderInfo orderInfo) {
		Long goodsId = orderInfo.getProductId();
		Long userId = orderInfo.getUserId();
		Integer credits = orderInfo.getCostCredits();

		minusProdExgNumLimit(goodsId);
		minusProdStock(goodsId);

		GoodsQuery query = GoodsQuery.builder()
				.onSell(1)
				.deleted(false)
				.goodsId(goodsId)
				.build();
		GoodsDO goodsDO = goodsMapper.getGoodsById(query);

		if (goodsDO == null) {
			throw new GoodsException(ErrorCode.GOODS_NOT_EXIST);
		}
		TransactionTemplate transactionTemplate = new TransactionTemplate(transactionManager);
		transactionTemplate.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);
		transactionTemplate.setTimeout(5);
		transactionTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED);
		return transactionTemplate.execute(status -> {
			String orderId = null;
			try {
				// 扣减积分
				boolean success = operationService.addUserScore(userId, Math.negateExact(credits),
						OperationRecordEm.PRODUCT_CONSUME);

				// 创建订单
				if (success) {
					orderId = orderService.createOrder(orderInfo);
					log.info("订单创建成功！订单编号：{}", orderId);
				}
			} catch (Exception e) {
				log.warn("创建订单失败，回滚库存，商品兑换次数数据...", e);
				rollbackProdStock(goodsId);
				rollbackProdExgNumLimit(goodsId);
				throw new GoodsException(ErrorCode.ORDER_OPERATION_ERROR);
			}
			return orderId;
		});
	}


	/**
	 * 判断商品的今日可兑换次数是否超限，若没有则减一
	 */
	private void minusProdExgNumLimit(Long productId) {
		String redisKey = genProductExgNum(productId);
		Long decr = redisService.decrement(redisKey);
		if (decr < 0) {
			rollbackProdExgNumLimit(productId);
			throw new GoodsException(ErrorCode.EXG_OVER_PROD_LIMIT);
		}
		log.info("扣减商品兑换次数成功,商品编号:{},剩余次数:{}", productId, decr);
	}


	public void rollbackProdExgNumLimit(Long productId) {
		String redisKey = genProductExgNum(productId);
		Long incr = redisService.increment(redisKey);
		log.info("商品每日兑换次数回滚后数据:{}", incr);
	}


	/**
	 * 判断商品的库存是否超限，若没有则减一
	 */
	private void minusProdStock(Long productId) {
		String redisKey = genProductStockNumRedisKey(productId);
		Long decr = redisService.decrement(redisKey);
		if (decr < 0) {
			rollbackProdStock(productId);
			rollbackProdExgNumLimit(productId);
			throw new GoodsException(ErrorCode.GOODS_NO_STOCK);
		}
		log.info("扣减商品库存成功,商品编号:{},剩余库存:{}", productId, decr);
	}


	public void rollbackProdStock(Long productId) {
		String redisKey = genProductStockNumRedisKey(productId);
		Long incr = redisService.increment(redisKey);
		log.info("库存回滚后数据:{}", incr);
	}


	public GoodsDO findById(Long goodsId) {
		GoodsQuery query = GoodsQuery.builder()
				.onSell(1)
				.deleted(false)
				.goodsId(goodsId)
				.build();
		return goodsMapper.getGoodsById(query);
	}


