				.goodsId(goodsId)
				.build();
		GoodsDO goodsDO = goodsMapper.getGoodsById(query);

		if (goodsDO == null) {
			throw new GoodsException(ErrorCode.GOODS_NOT_EXIST);
		}

		checkProdIsOnSell(goodsDO);

		checkProdInExgTime(goodsDO);

		checkCustExgNumLimit(userId, goodsDO);

		checkCustCreditsIsValid(userId, goodsDO);
