	/**
	 * 每个用户是否超过了当日兑换次数
	 */
	public boolean isCustOverProdOneDayExgLimit(Long userId, Long productId, Integer exNumPerDay) {
		OrderRecordDO orderRecordDO = orderService.getOrderRecord(userId, productId,
				CreditsTypeEnum.PRODUCT.getType(), LocalDate.now());
		if (orderRecordDO != null) {
			boolean flag = orderRecordDO.getTimes() >= exNumPerDay;
			if (flag) {
				log.info("用户：{}，超过了该商品的今日可兑换次数，商品编号：{}，已兑换次数：{}，商品单日最高用户可兑换次数：{}", userId, productId,
						orderRecordDO.getTimes(), exNumPerDay);
			}
			return flag;
		}
		return false;
	}

	/**
	 * 每个用户是否超过了n日兑换次数
	 */
	public boolean isCustOverProdNdayExgLimit(Long userId, Long productId, Integer exTotalDay, Integer exTotalNum) {
		OrderRecordDO orderRecord = orderService.getOrderRecord(userId, productId,
				CreditsTypeEnum.PRODUCT.getType(), LocalDate.now(), LocalDate.now().minusDays(exTotalDay - 1));
		if (orderRecord != null) {
			boolean flag = orderRecord.getTimes() >= exTotalNum;
			if (flag) {
				log.info("用户：{}，超过了该商品的n日可兑换次数，商品编号:{}，已兑换次数:{}，商品n日最高用户可兑换次数:{}，n为：{}", userId, productId,
						orderRecord.getTimes(), exTotalNum, exTotalDay);
			}
			return flag;
		}
		return false;
	}


	/**
	 * 判断用户兑换数量是否超过基础配置中配置的次数总量
	 */
	private void isCustOverTotalOneDayExgLimit(Long custId) {
		// 总的天数
		Integer exTotalDay = appConfig.getExNumTotalDay();
		LocalDate endTime = LocalDate.now();
		LocalDate startTime = endTime.minusDays(exTotalDay - 1);
		// 每个用户一天内兑换的所有商品次数
		OrderRecordDO oneDayOrderRecord = orderService.getOrderRecord(custId, CreditsTypeEnum.PRODUCT.getType(),
				endTime);

		if (oneDayOrderRecord != null) {
			Integer oneDayOrderCount = oneDayOrderRecord.getTimes();
			if (oneDayOrderCount >= appConfig.getExNumPerDay()) {
				log.info("用户：{}，超过了今日可兑换次数的基本配置，已兑换次数:{}，商品单日最高用户可兑换次数:{}", custId, oneDayOrderCount,
						appConfig.getExNumPerDay());
				throw new GoodsException(ErrorCode.EXG_OVER_ONEDAY_LIMIT);
			}
		}

		// 每个用户n天内兑换的所有商品次数
		OrderRecordDO ndayOrderRecord = orderService.getOrderRecord(custId, CreditsTypeEnum.PRODUCT.getType(),
				startTime, endTime);
		if (ndayOrderRecord != null) {
			Integer ndayOrderCount = ndayOrderRecord.getTimes();
			if (ndayOrderCount >= appConfig.getExNumTotal()) {
				log.info("用户：{}，超过了该商品的n日可兑换次数，已兑换次数:{}，商品n日最高用户可兑换次数:{}，n为：{}", custId, ndayOrderCount,
						appConfig.getExNumTotal(), exTotalDay);
				throw new GoodsException(ErrorCode.CREDITS_OVER_NDAY_LIMIT, new Object[]{exTotalDay});
			}
		}

	}


