	/**
	 * 检查用户信息
	 */
	private void checkUserStatus(Long userId) {
		UserDO userDO = userService.getUserById(userId);
		if (userDO == null) {
			throw new GoodsException(ErrorCode.USER_NOT_EXIST);
		}

		UserGatherDO userGatherDO = operationService.getUserGather(userId);

		if (userGatherDO == null) {
			throw new GoodsException(ErrorCode.NOT_ENOUGH_CREDITS);
		}

		if (userGatherDO.getIsFreeze()) {
			throw new GoodsException(ErrorCode.USER_FREEZE);
		}

		if (StringUtils.isBlank(userDO.getMobile())) {
			throw new GoodsException(ErrorCode.USER_NO_BIND_MOBILE);
		}

	}

	public List<GoodsRecommendDO> getRecommendGoods() {
		List<GoodsRecommendDO> goodsRecommendDOS = goodsMapper.queryRecommendGoods();
		for (GoodsRecommendDO goodsRecommendDO : goodsRecommendDOS) {
			GoodsDO goodsDO = getById(goodsRecommendDO.getGoodsId());
			goodsRecommendDO.setGoods(goodsDO);
		}
		return goodsRecommendDOS;
	}

	public List<GoodsDO> getByIds(List<Long> goodsIdList) {
		List<GoodsDO> goodsList = new ArrayList<>();
		goodsIdList.forEach(goodId -> {
			GoodsDO goodsDO = getById(goodId);
			goodsList.add(goodsDO);
		});
		return goodsList;
	}

	/**
	 * 该方式，适合课程商品，别的商品不要用该方法判断
	 */
	public boolean queryPurchased(Long userId, Long goodsId) {
		OrderDO orderDO = orderService.findByUserIdAndGoodsId(userId, goodsId);
		if (orderDO == null) {
			return false;
		}
		return OrderUtil.isPaySuccess(orderDO);
	}

	/**
	 * 该方式，适合课程商品，别的商品不要用该方法判断
	 */
	public List<Long> queryPurchasedList(Long userId, List<Long> goodsIdList) {
		List<Long> result = new ArrayList<>();
		List<OrderDO> orderDOList = orderService.findByUserIdAndGoodsIdList(userId, goodsIdList);
		if (orderDOList == null || orderDOList.isEmpty()) {
			return result;
		}
		for (OrderDO orderDO : orderDOList) {
			if (OrderUtil.isPaySuccess(orderDO)) {
				List<OrderGoodsDO> orderGoodsList = orderGoodsService.queryByOrderId(orderDO.getId());
				orderGoodsList.forEach(orderGoodsDO -> {
					result.add(orderGoodsDO.getGoodsId());
				});
			}
		}
		return result;
	}
}

