package com.education.music.app.controller;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultHandlers.print;

import cn.hutool.json.JSONUtil;
import com.education.music.app.entity.req.ClassUserReq;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import org.springframework.http.MediaType;

public class ClassControllerTest extends CommonTest {

	@Test
	public void searchList() throws Exception {
		Map<String, Object> map = new HashMap<>();
		map.put("userId", 3);
		map.put("pageSize", 10);
		map.put("lastId", 132);
		map.put("startTime", "");
		map.put("endTime", "");
		map.put("keyword", "");
		map.put("keyType", "");
		String content = JSONUtil.toJsonStr(map);
		mockMvc.perform(post("/class/searchList")
				.accept(MediaType.APPLICATION_JSON_UTF8)
				.contentType(MediaType.APPLICATION_JSON)
				.header("authorization", teacherJwtToken)
				.content(content)
				.session(session))
				.andDo(print());
	}

	@Test
	public void addClass() throws Exception {
		List<ClassUserReq> userList = new ArrayList<>();
		ClassUserReq user1 = new ClassUserReq();
		user1.setUserId(1L);

		ClassUserReq user2 = new ClassUserReq();
		user2.setUserId(2L);

		userList.add(user1);
		userList.add(user2);

		Map<String, Object> map = new HashMap<>();
		map.put("name", "班级1");
		map.put("desc", "班级描述");
		map.put("userList", userList);

		String content = JSONUtil.toJsonStr(map);
		mockMvc.perform(post("/class/addOrUpdate")
				.accept(MediaType.APPLICATION_JSON_UTF8)
				.contentType(MediaType.APPLICATION_JSON)
				.header("authorization", teacherJwtToken)
				.content(content)
				.session(session))
				.andDo(print())
				.andReturn();
	}

	@Test
	public void updateClass() throws Exception {
		List<ClassUserReq> userList = new ArrayList<>();
		ClassUserReq user1 = new ClassUserReq();
		user1.setUserId(3L);

		ClassUserReq user2 = new ClassUserReq();
		user2.setUserId(4L);

		userList.add(user1);
		userList.add(user2);

		Map<String, Object> map = new HashMap<>();
		map.put("classId", 120);
		map.put("name", "班级2");
		map.put("desc", "班级描述2");
		map.put("userList", userList);

		String content = JSONUtil.toJsonStr(map);
		mockMvc.perform(post("/class/addOrUpdate")
				.accept(MediaType.APPLICATION_JSON_UTF8)
				.contentType(MediaType.APPLICATION_JSON)
				.header("authorization", teacherJwtToken)
				.content(content)
				.session(session))
				.andDo(print())
				.andReturn();
	}

	@Test
	public void delClass() throws Exception {
		Map<String, Object> map = new HashMap<>();
		map.put("id", 119);
		String content = JSONUtil.toJsonStr(map);
		mockMvc.perform(post("/class/del")
				.accept(MediaType.APPLICATION_JSON_UTF8)
				.contentType(MediaType.APPLICATION_JSON)
				.header("authorization", teacherJwtToken)
				.content(content)
				.session(session))
				.andDo(print());
	}

	@Test
	public void importCourseTemplate() throws Exception {
		Map<String, Object> map = new HashMap<>();
		map.put("classId", 120);
		map.put("templateId", 118);
		String content = JSONUtil.toJsonStr(map);
